26	static constexpr int64_t NUM_ZERO = 0;
27	static constexpr int64_t NUM_ONE = 1;
28	static constexpr int64_t NUM_TWO = 2;
29	static constexpr int64_t NUM_THREE = 3;
30	static constexpr int64_t NUM_FOUR = 4;
31	static constexpr int64_t NUM_FIVE = 5;
32	static constexpr int64_t NUM_SIX = 6;
33	static constexpr int64_t NUM_SEVEN = 7;
34	static constexpr int64_t NUM_EIGHT = 8;
35	static constexpr int64_t FOURTY = 40;
36	static constexpr int64_t FOURTY_EIGHT = 48;
37	
38	// ------------------算子原型索引常量定义----------------
39	// Inputs Index
40	static constexpr int64_t INPUT_INDEX = 0;
41	static constexpr int64_t WEIGHT_INDEX = 1;
42	static constexpr int64_t MASK_INDEX = 2;
43	
44	// Outputs Index
45	static constexpr int64_t OUTPUT_INDEXER = 0;
46	
47	// Dim Num
48	static constexpr int64_t DIM_NUM_TWO = 2;
49	static constexpr int64_t DIM_NUM_THREE = 3;
50	
51	// Dim Index
52	static constexpr int64_t DIM_IDX_ZERO = 0;
53	static constexpr int64_t DIM_IDX_ONE = 1;
54	static constexpr int64_t DIM_IDX_TWO = 2;
55	static constexpr int64_t DIM_IDX_THREE = 3;
56	
57	// 入参限制常量
58	static constexpr int64_t S_SIZE_LIMIT = 32 * 1024;  // 32K
59	static constexpr int64_t B_SIZE_LIMIT = 8;
60	static constexpr int64_t H_SIZE_UP_LIMIT = 24576;  // 192*128
61	static constexpr int64_t H_SIZE_DOWN_LIMIT = 384;  // 192*2
62	static constexpr int64_t W_SIZE_LIMIT = 3;         // 卷积的窗口固定是3
63	static constexpr int64_t H_SIZE_FULL = 4096;       // UB全载时，H最大是4096
64	
65	// workspace上预留100M
66	static constexpr int64_t DEFAULT_WORKSPACE_SIZE = 100 * 1024 * 1024;
