104	ge::graphStatus AHInfoParser::CheckInputValid()
105	{
106	    // 1.获取变量相关参数
107	    opParamInfo_.input.desc = context_->GetInputDesc(INPUT_INDEX);
108	    opParamInfo_.input.shape = context_->GetInputShape(INPUT_INDEX);
109	    // 2.检查变量是否存在
110	    OP_CHECK_IF(opParamInfo_.input.shape == nullptr,
111	        OP_LOGE(opName_, "Shape of tensor input is nullptr"),
112	        return ge::GRAPH_FAILED);
113	    OP_CHECK_IF(opParamInfo_.input.desc == nullptr,
114	        OP_LOGE(opName_, "Desc of tensor input is nullptr"),
115	        return ge::GRAPH_FAILED);
116	    // 3.检查变量类型
117	    inputType_ = opParamInfo_.input.desc->GetDataType();
118	    OP_CHECK_IF(((inputType_ != ge::DT_FLOAT16) && (inputType_ != ge::DT_BF16)),
119	        OP_LOGE(opName_, "The data types of the input must be float16 or bfloat16."),
120	        return ge::GRAPH_FAILED);
121	    // 4.检查变量Shape的Dim
122	    int64_t inputShapeDim = opParamInfo_.input.shape->GetStorageShape().GetDimNum();
123	    int64_t inputExpectShapeDim = DIM_NUM_THREE;
124	    OP_CHECK_IF(inputShapeDim != inputExpectShapeDim,
125	        OP_LOGE(
126	            opName_, "the dim num of input's shape should be %u, but now is %u", inputExpectShapeDim, inputShapeDim),
127	        return ge::GRAPH_FAILED);
128	    // 5.检查变量shape大小是否超限 input [S,B,H],
129	    //  -----------------------check S Size-------------------
130	    sSize_ = static_cast<int64_t>(opParamInfo_.input.shape->GetStorageShape().GetDim(DIM_IDX_ZERO));
131	    OP_LOGI(context_->GetNodeName(), "sSize is %d", sSize_);
132	    OP_CHECK_IF(sSize_ > S_SIZE_LIMIT,
133	        OP_LOGE(opName_, "the max of S size only support 32K, but now is %d.", sSize_),
134	        return ge::GRAPH_FAILED);
135	    // -----------------------check B Size-------------------
136	    bSize_ = static_cast<int64_t>(opParamInfo_.input.shape->GetStorageShape().GetDim(DIM_IDX_ONE));
137	    OP_LOGI(context_->GetNodeName(), "bSize is %d", bSize_);
138	    OP_CHECK_IF(bSize_ > B_SIZE_LIMIT,
139	        OP_LOGE(opName_, "the max of batch size only support 8, but now is %d.", bSize_),
140	        return ge::GRAPH_FAILED);
141	    // -----------------------check H Size-------------------
142	    hSize_ = static_cast<int64_t>(opParamInfo_.input.shape->GetStorageShape().GetDim(DIM_IDX_TWO));
143	    OP_LOGI(context_->GetNodeName(), "hSize is %d", hSize_);
144	    OP_CHECK_IF(hSize_ > H_SIZE_UP_LIMIT,
145	        OP_LOGE(opName_, "the max of H size must smaller than 24576, but now is %d.", hSize_),
146	        return ge::GRAPH_FAILED);
147	    OP_CHECK_IF(hSize_ < H_SIZE_DOWN_LIMIT,
148	        OP_LOGE(opName_, "the min of H size must larger than 384, but now is %d.", hSize_),
149	        return ge::GRAPH_FAILED);
150	
151	    return ge::GRAPH_SUCCESS;
152	}
