154	ge::graphStatus AHInfoParser::CheckWeightValid()
155	{
156	    // 1.获取变量相关参数
157	    opParamInfo_.weight.desc = context_->GetInputDesc(WEIGHT_INDEX);
158	    opParamInfo_.weight.shape = context_->GetInputShape(WEIGHT_INDEX);
159	    // 2.检查变量是否存在
160	    OP_CHECK_IF(opParamInfo_.weight.shape == nullptr,
161	        OP_LOGE(opName_, "Shape of tensor weight is nullptr"),
162	        return ge::GRAPH_FAILED);
163	    OP_CHECK_IF(opParamInfo_.weight.desc == nullptr,
164	        OP_LOGE(opName_, "Desc of tensor weight is nullptr"),
165	        return ge::GRAPH_FAILED);
166	    // 3.检查变量类型
167	    weightType_ = opParamInfo_.weight.desc->GetDataType();
168	    OP_CHECK_IF((inputType_ != weightType_),
169	        OP_LOGE(opName_, "The data types of the input and weight must be the same."),
170	        return ge::GRAPH_FAILED);
171	    // 4. 检查变量Shape的Dim
172	    int64_t weightShapeDim = opParamInfo_.weight.shape->GetStorageShape().GetDimNum();
173	    int64_t weightExpectShapeDim = DIM_NUM_TWO;
174	    OP_CHECK_IF(weightShapeDim != weightExpectShapeDim,
175	        OP_LOGE(
176	            opName_, "the dim num of weight's shape should be %u, but now is %u", weightExpectShapeDim, weightShapeDim),
177	        return ge::GRAPH_FAILED);
178	    // 5.检查变量shape大小是否超限,weight [W=3,H]
179	    //  -----------------------check W Size-------------------
180	    OP_CHECK_IF((opParamInfo_.weight.shape->GetStorageShape().GetDim(DIM_IDX_ZERO) != W_SIZE_LIMIT),
181	        OP_LOGE(opName_, "The window size of convolution must be 3."),
182	        return ge::GRAPH_FAILED);
183	    // 6.检查变量shape大小是否与input一致
184	    //  -----------------------check H Size-------------------
185	    OP_CHECK_IF((opParamInfo_.weight.shape->GetStorageShape().GetDim(DIM_IDX_ONE) != hSize_),
186	        OP_LOGE(opName_,
187	            "Input dim 2 and Weight dim 1 is %u, %u respectively, they must be same.",
188	            opParamInfo_.input.shape->GetStorageShape().GetDim(DIM_IDX_TWO),
189	            opParamInfo_.weight.shape->GetStorageShape().GetDim(DIM_IDX_ONE)),
190	        return ge::GRAPH_FAILED);
191	
192	    return ge::GRAPH_SUCCESS;
193	}
