232	ge::graphStatus AHInfoParser::CheckOutputValid()
233	{
234	    // 1.获取变量相关参数
235	    opParamInfo_.output.desc = context_->GetOutputDesc(OUTPUT_INDEXER);
236	    opParamInfo_.output.shape = context_->GetOutputShape(OUTPUT_INDEXER);
237	    // 2.检查变量是否存在
238	    OP_CHECK_IF(opParamInfo_.output.shape == nullptr,
239	        OP_LOGE(opName_, "Shape of tensor output is nullptr"),
240	        return ge::GRAPH_FAILED);
241	    OP_CHECK_IF(opParamInfo_.output.desc == nullptr,
242	        OP_LOGE(opName_, "Desc of tensor output is nullptr"),
243	        return ge::GRAPH_FAILED);
244	    // 3.检查变量类型
245	    outputType_ = opParamInfo_.output.desc->GetDataType();
246	    OP_CHECK_IF((inputType_ != outputType_),
247	        OP_LOGE(opName_, "The data types of the input and output must be the same."),
248	        return ge::GRAPH_FAILED);
249	    // 4. 检查变量Shape的Dim
250	    int64_t outputShapeDim = opParamInfo_.output.shape->GetStorageShape().GetDimNum();
251	    int64_t outputExpectShapeDim = DIM_NUM_THREE;
252	    OP_CHECK_IF(outputShapeDim != outputExpectShapeDim,
253	        OP_LOGE(
254	            opName_, "the dim num of output's shape should be %u, but now is %u", outputExpectShapeDim, outputShapeDim),
255	        return ge::GRAPH_FAILED);
256	    // 5.检查变量shape大小是否与input一致, output [S,B,H]
257	    //  -----------------------check S Size-------------------
258	    OP_CHECK_IF((opParamInfo_.output.shape->GetStorageShape().GetDim(DIM_IDX_ZERO) != sSize_),
259	        OP_LOGE(opName_,
260	            "Input and Output dim 0 is %u, %u respectively, they must be same.",
261	            opParamInfo_.input.shape->GetStorageShape().GetDim(DIM_IDX_ZERO),
262	            opParamInfo_.output.shape->GetStorageShape().GetDim(DIM_IDX_ZERO)),
263	        return ge::GRAPH_FAILED);
264	    // -----------------------check B Size-------------------
265	    OP_CHECK_IF((opParamInfo_.output.shape->GetStorageShape().GetDim(DIM_IDX_ONE) != bSize_),
266	        OP_LOGE(opName_,
267	            "Input and Output dim 1 is %u, %u respectively, they must be same.",
268	            opParamInfo_.input.shape->GetStorageShape().GetDim(DIM_IDX_ONE),
269	            opParamInfo_.output.shape->GetStorageShape().GetDim(DIM_IDX_ONE)),
270	        return ge::GRAPH_FAILED);
271	    // -----------------------check H Size-------------------
272	    OP_CHECK_IF((opParamInfo_.output.shape->GetStorageShape().GetDim(DIM_IDX_TWO) != hSize_),
273	        OP_LOGE(opName_,
274	            "Input dim 2 and Output dim 2 is %u, %u respectively, they must be same.",
275	            opParamInfo_.input.shape->GetStorageShape().GetDim(DIM_IDX_TWO),
276	            opParamInfo_.output.shape->GetStorageShape().GetDim(DIM_IDX_TWO)),
277	        return ge::GRAPH_FAILED);
278	
279	    return ge::GRAPH_SUCCESS;
280	}
