355	void AHInfoParser::GenerateInfo(AHTilingInfo &ahInfo)
356	{
357	    ahInfo.opName = opName_;
358	    ahInfo.platformInfo = platformInfo_;
359	    ahInfo.opParamInfo = opParamInfo_;
360	    ahInfo.socVersion = socVersion_;
361	
362	    ahInfo.ifMask = ifMask_;
363	    ahInfo.sSize = sSize_;
364	    ahInfo.bSize = bSize_;
365	    ahInfo.hSize = hSize_;
366	    ahInfo.baseS = baseS_;
367	    ahInfo.baseB = baseB_;
368	    ahInfo.baseH = baseH_;
369	    ahInfo.baseSTail = baseSTail_;
370	    ahInfo.baseBTail = baseBTail_;
371	    ahInfo.baseHTail = baseHTail_;
372	    ahInfo.baseSCnt = baseSCnt_;
373	    ahInfo.baseBCnt = baseBCnt_;
374	    ahInfo.baseHCnt = baseHCnt_;
375	    ahInfo.tilingKey = tilingKey_;
376	    ahInfo.blockDim = blockDim_;
377	}
