425	// --------------------------AiInfraAggregateHiddenTiling类成员函数定义-----------------------
426	ge::graphStatus AiInfraAggregateHiddenTiling::DoTiling(AHTilingInfo *tilingInfo)
427	{
428	    // -------------set blockdim-----------------
429	    context_->SetBlockDim(static_cast<uint32_t>(tilingInfo->blockDim));
430	    // -------------set workspacesize-----------------
431	    size_t *workSpaces = context_->GetWorkspaceSizes(1);
432	    if (workSpaces == nullptr) {
433	        return ge::GRAPH_FAILED;
434	    }
435	    workSpaces[0] = DEFAULT_WORKSPACE_SIZE;
436	
437	    // -------------set tilingdata-----------------
438	    tilingData_.set_ifMask(tilingInfo->ifMask);
439	    tilingData_.set_sSize(tilingInfo->sSize);
440	    tilingData_.set_bSize(tilingInfo->bSize);
441	    tilingData_.set_hSize(tilingInfo->hSize);
442	    tilingData_.set_baseS(tilingInfo->baseS);
443	    tilingData_.set_baseB(tilingInfo->baseB);
444	    tilingData_.set_baseH(tilingInfo->baseH);
445	    tilingData_.set_baseSTail(tilingInfo->baseSTail);
446	    tilingData_.set_baseBTail(tilingInfo->baseBTail);
447	    tilingData_.set_baseHTail(tilingInfo->baseHTail);
448	    tilingData_.set_baseSCnt(tilingInfo->baseSCnt);
449	    tilingData_.set_baseBCnt(tilingInfo->baseBCnt);
450	    tilingData_.set_baseHCnt(tilingInfo->baseHCnt);
451	
452	    tilingData_.SaveToBuffer(context_->GetRawTilingData()->GetData(), context_->GetRawTilingData()->GetCapacity());
453	    context_->GetRawTilingData()->SetDataSize(tilingData_.GetDataSize());
454	
455	    // -------------set tilingkey-----------------
456	    // 根据输入数据类型的不同区分tiling key
457	    context_->SetTilingKey(tilingInfo->tilingKey);
458	
459	    return ge::GRAPH_SUCCESS;
460	}
461	
462	// --------------------------Tiling函数定义---------------------------
463	ge::graphStatus TilingForAiInfraAggregateHidden(gert::TilingContext *context)
464	{
465	    OP_CHECK_IF(context == nullptr,
466	        OPS_REPORT_VECTOR_INNER_ERR("AiInfraAggregateHidden", "Tiling context is null."),
467	        return ge::GRAPH_FAILED);
468	    AHTilingInfo ahInfo;
469	    AHInfoParser ahInfoParser(context);
470	    if (ahInfoParser.ParseAndCheck(ahInfo) != ge::GRAPH_SUCCESS) {
471	        return ge::GRAPH_FAILED;
472	    }
473	    AiInfraAggregateHiddenTiling ahTiling(context);
474	    return ahTiling.DoTiling(&ahInfo);
475	}
476	
477	// --------------------------Tiling函数及TilingPrepare函数注册--------
478	IMPL_OP_OPTILING(AiInfraAggregateHidden)
479	    .Tiling(TilingForAiInfraAggregateHidden)
480	    .TilingParse<AiInfraAggregateHiddenCompileInfo>(TilingPrepareForAiInfraAggregateHidden);
481	
482	}  // namespace optiling
