23	template <typename DTYPE>
24	class KernelAiInfraAggregateHidden : public KernelAiInfraAggregateHiddenCutHBS<DTYPE> {
25	public:
26	    __aicore__ inline KernelAiInfraAggregateHidden(TPipe *pipe, const AiInfraAggregateHiddenTilingData *tiling)
27	        : KernelAiInfraAggregateHiddenCutHBS<DTYPE>(pipe, tiling)
28	    {}
29	
30	    __aicore__ inline void Init(GM_ADDR input, GM_ADDR weight, GM_ADDR mask, GM_ADDR output)
31	    {
32	        this->InitSharedData();
33	        this->inputGm.SetGlobalBuffer((__gm__ DTYPE *)input);    //  [sSize, bSize, hSize]
34	        this->weightGm.SetGlobalBuffer((__gm__ DTYPE *)weight);  //  [3, hSize]
35	        if (this->tilingData_->ifMask) {
36	            this->maskGm.SetGlobalBuffer((__gm__ bool *)mask);  //  [bSize, sSize]
37	        }
38	        this->outputGm.SetGlobalBuffer((__gm__ DTYPE *)output);  //  [sSize, bSize, hSize]
39	
40	        // max alignBaseH = 4096 -> 4K
41	        this->pipe_->InitBuffer(
42	            this->inQueueX, NUM_TWO, this->alignBaseH * sizeof(DTYPE));       // 2 * alignBaseH * 2 / 1024 = 16K
43	        this->pipe_->InitBuffer(this->y2, this->alignBaseH * sizeof(float));  // alignBaseH * 4 / 1024 = 16K
44	        this->pipe_->InitBuffer(this->y1, this->alignBaseH * sizeof(float));  // alignBaseH * 4 / 1024 = 16K
45	        this->pipe_->InitBuffer(this->y0, this->alignBaseH * sizeof(float));  // alignBaseH * 4 / 1024 = 16K
46	        this->pipe_->InitBuffer(this->inQueueW,
47	            NUM_TWO,
48	            NUM_THREE * this->alignBaseH * sizeof(float));  // 2 * 3 * alignBaseH * 4 / 1024 = 96K
49	        this->pipe_->InitBuffer(this->inputFp32, this->alignBaseH * sizeof(float));  // alignBaseH * 4 / 1024 = 16K
50	        this->pipe_->InitBuffer(
51	            this->outQueue, NUM_TWO, this->alignBaseH * sizeof(DTYPE));  //  2 * alignBaseH * 2 / 1024 = 16K
52	    }
53	
54	    __aicore__ inline void Process()
55	    {
56	        // CopyIn weight
57	        LocalTensor<float> weightFp32 = this->inQueueW.template AllocTensor<float>();
58	        LocalTensor<DTYPE> localW0 = weightFp32.template ReinterpretCast<DTYPE>()[this->alignBaseH];
59	        LocalTensor<DTYPE> localW1 = localW0[this->alignBaseH * NUM_TWO];
60	        LocalTensor<DTYPE> localW2 = localW1[this->alignBaseH * NUM_TWO];
61	        DataCopyPadExtParams<DTYPE> padParams{false, 0, 0, 0};
62	        DataCopyExtParams copyParamsContinguous;
63	        copyParamsContinguous.blockCount = NUM_THREE;  // weight [3, hSize]
64	        copyParamsContinguous.blockLen = this->baseH * sizeof(DTYPE);
65	        copyParamsContinguous.srcStride = (this->tilingData_->hSize - this->baseH) * sizeof(DTYPE);
66	        copyParamsContinguous.dstStride = this->alignBaseH * sizeof(DTYPE) / BLOCK_SIZE;
67	        int64_t gmOffset = this->tilingData_->baseH *
68	                           this->baseHIdx;  // this->baseH 可能更改为尾块大小了 所以这里要用this->tilingData->baseH
69	        DataCopyPad(localW0, this->weightGm[gmOffset], copyParamsContinguous, padParams);
70	        this->inQueueW.EnQue(weightFp32);
71	        weightFp32 = this->inQueueW.template DeQue<float>();
72	        localW0 = weightFp32.template ReinterpretCast<DTYPE>()[this->alignBaseH];
73	        localW1 = localW0[this->alignBaseH * NUM_TWO];
74	        localW2 = localW1[this->alignBaseH * NUM_TWO];
75	        LocalTensor<float> localW0FP32 = weightFp32;
76	        LocalTensor<float> localW1FP32 = weightFp32[this->alignBaseH];
77	        LocalTensor<float> localW2FP32 = weightFp32[this->alignBaseH * NUM_TWO];
78	        Cast(localW0FP32, localW0, RoundMode::CAST_NONE, this->alignBaseH);
79	        Cast(localW1FP32, localW1, RoundMode::CAST_NONE, this->alignBaseH);
80	        Cast(localW2FP32, localW2, RoundMode::CAST_NONE, this->alignBaseH);
81	        this->inQueueW.EnQue(weightFp32);
82	        weightFp32 = this->inQueueW.template DeQue<float>();
83	
84	        LocalTensor<float> y0Fp32 = this->y0.template Get<float>();
85	        LocalTensor<float> y1Fp32 = this->y1.template Get<float>();
86	        LocalTensor<float> y2Fp32 = this->y2.template Get<float>();
87	        for (int64_t bIdx = 0; bIdx < this->baseB; ++bIdx) {
88	            InitY<DTYPE>(y0Fp32, y1Fp32, weightFp32, bIdx);
89	            for (int64_t sIdx = 0; sIdx < this->baseS; ++sIdx) {
90	                LocalTensor<DTYPE> xLocal = this->inQueueX.template AllocTensor<DTYPE>();
91	                CopyIn<DTYPE>(xLocal, bIdx, sIdx);
92	                this->inQueueX.EnQue(xLocal);
93	                xLocal = this->inQueueX.template DeQue<DTYPE>();
94	                LocalTensor<float> xLocalFp32 = this->inputFp32.template Get<float>();
95	                Cast(xLocalFp32, xLocal, RoundMode::CAST_NONE, this->alignBaseH);
96	                this->inQueueX.FreeTensor(xLocal);
97	                Compute<DTYPE>(xLocalFp32, weightFp32, y0Fp32, y1Fp32, y2Fp32, bIdx, sIdx);
98	                CopyOut<DTYPE>(y2Fp32, this->outputGm, bIdx, sIdx);
99	            }
100	        }
101	        this->inQueueW.FreeTensor(weightFp32);
102	    }
103	
104	    template <typename T>
105	    __aicore__ inline void InitY(const LocalTensor<float> &y0Fp32, const LocalTensor<float> &y1Fp32,
106	        const LocalTensor<float> &weightFp32, int64_t bIdx)
107	    {
108	        if (this->baseSIdx == NUM_ZERO) {
109	            Duplicate(y0Fp32, static_cast<float>(0.0f), this->alignBaseH);
110	            Duplicate(y1Fp32, static_cast<float>(0.0f), this->alignBaseH);
111	            PipeBarrier<PIPE_V>();
112	        } else {
113	            // CopyIn input[sSize-2]
114	            int64_t startSIdx = this->tilingData_->baseS * this->baseSIdx;
115	            int64_t preSIdx = startSIdx - NUM_TWO;
116	            int64_t startBIdx = this->tilingData_->baseB * this->baseBIdx + bIdx;
117	            int64_t gmOffset4Y0 = preSIdx * this->tilingData_->bSize * this->tilingData_->hSize +
118	                                  startBIdx * this->tilingData_->hSize + this->baseHIdx * this->tilingData_->baseH;
119	            int64_t gmOffset4Y1 = (preSIdx + NUM_ONE) * this->tilingData_->bSize * this->tilingData_->hSize +
120	                                  startBIdx * this->tilingData_->hSize + this->baseHIdx * this->tilingData_->baseH;

